import { useEffect, useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import { Link } from 'react-router-dom';
import { Activity, ArrowDownLeft, ArrowUpRight, Check, CircleDollarSign, ClipboardList, CreditCard, Copy, Edit3, KeyRound, FileText, Globe2, Headphones, LayoutDashboard, Plus, RefreshCw, Search, Server, ShieldCheck, Users, Wallet, X } from 'lucide-react';
import { api, useResource, money, date, gb, trafficGB, subscriptionGB, serviceReason } from './lib';
import type { Article, Audit, Commission, Ledger, Node, Order, Plan, Subscription, Ticket, TrafficRecord, TrafficEnforcement, User, Withdrawal } from './types';
import { Hero, Card, Stat, Empty, Modal, Status, Spinner, useToast } from './ui';

type Column<T> = { label: string; render: (row: T) => ReactNode };
function Table<T extends { id: number | string }>({ columns, rows, empty = '暂无记录' }: { columns: Column<T>[]; rows: T[]; empty?: string }) {
  if (!rows.length) return <Empty title={empty} description="数据产生后会显示在这里。" />;
  return <div className="table-wrap"><table className="data-table"><thead><tr>{columns.map((c) => <th key={c.label}>{c.label}</th>)}</tr></thead><tbody>{rows.map((row) => <tr key={row.id}>{columns.map((c) => <td key={c.label}>{c.render(row)}</td>)}</tr>)}</tbody></table></div>;
}
function Load({ loading, error, reload, children }: { loading: boolean; error: string; reload: () => Promise<void>; children: ReactNode }) {
  if (loading) return <Card><Spinner /></Card>;
  if (error) return <Card><Empty title="暂时无法读取数据" description={error} action={<button className="button button-primary" onClick={() => void reload()}><RefreshCw size={16} />重新加载</button>} /></Card>;
  return <>{children}</>;
}
function SearchBox({ value, setValue, placeholder = '搜索记录…' }: { value: string; setValue: (value: string) => void; placeholder?: string }) {
  return <label className="search-field"><Search size={17} /><input aria-label={placeholder} value={value} onChange={(e) => setValue(e.target.value)} placeholder={placeholder} /></label>;
}
function Refresh({ reload }: { reload: () => Promise<void> }) { return <button className="button button-ghost" onClick={() => void reload()}><RefreshCw size={15} />刷新</button>; }
function Field({ label, children, full }: { label: string; children: ReactNode; full?: boolean }) { return <label className={`form-field${full ? ' full-width' : ''}`}><span>{label}</span>{children}</label>; }
function CheckField({ label, value, setValue }: { label: string; value: boolean; setValue: (v: boolean) => void }) { return <label className="field-row"><input type="checkbox" checked={value} onChange={(e) => setValue(e.target.checked)} /><span>{label}</span></label>; }
function Submit({ saving, onClose, label = '保存修改' }: { saving: boolean; onClose: () => void; label?: string }) { return <div className="actions full-width" style={{ justifyContent: 'flex-end', marginTop: 12 }}><button type="button" className="button button-ghost" onClick={onClose}>取消</button><button className="button button-primary" type="submit" disabled={saving}>{saving ? '正在保存…' : label}</button></div>; }
function normalizedError(err: unknown) { return err instanceof Error ? err.message : '操作失败，请稍后重试'; }
function dateInput(value: string) { const parsed = new Date(value); if (Number.isNaN(parsed.getTime())) return ''; const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(parsed); const part = (name: Intl.DateTimeFormatPartTypes) => parts.find((p) => p.type === name)?.value || ''; return `${part('year')}-${part('month')}-${part('day')}`; }
const periodNames: Record<string, string> = { monthly: '月付', quarterly: '季付', yearly: '年付', onetime: '一次性', month: '月付', quarter: '季付', year: '年付' };

type Stats = { users: number; orders: number; revenue: number; active_subscriptions: number; nodes: number; open_tickets: number; pending_withdrawals: number; traffic_gb: number };
function Overview() {
  const r = useResource<Stats>('/admin/stats');
  const s = r.data;
  return <div className="page-stack"><Hero title="运营概览" description="在一个工作台查看账户、订阅与服务的运营情况。"><Refresh reload={r.reload} /></Hero><Load {...r}>{s && <div className="stats-grid"><Stat label="注册用户" value={s.users} icon={<Users size={23} />} tone="purple" /><Stat label="累计订单" value={s.orders} icon={<ClipboardList size={23} />} tone="blue" /><Stat label="已支付收入" value={money(s.revenue)} icon={<CircleDollarSign size={23} />} tone="orange" /><Stat label="有效订阅" value={s.active_subscriptions} icon={<ShieldCheck size={23} />} tone="green" /><Stat label="配置节点" value={s.nodes} icon={<Server size={23} />} tone="blue" /><Stat label="待处理工单" value={s.open_tickets} icon={<Headphones size={23} />} tone="purple" /><Stat label="待审核提现" value={s.pending_withdrawals} icon={<Wallet size={23} />} tone="orange" /><Stat label="记录总流量" value={gb(s.traffic_gb)} icon={<Activity size={23} />} tone="green" /></div>}</Load><div className="grid-2"><Card><div className="card-header"><h2>常用管理</h2><LayoutDashboard size={20} /></div><div className="detail-grid">{[['/admin/users', '用户与账户', Users], ['/admin/plans', '套餐与价格', CreditCard], ['/admin/nodes', '节点配置', Server], ['/admin/tickets', '客户工单', Headphones]].map(([to, label, Icon]) => { const I = Icon as typeof Users; return <Link className="button button-ghost" style={{ justifyContent: 'flex-start' }} key={String(to)} to={String(to)}><I size={18} />{String(label)}</Link>; })}</div></Card><Card><div className="card-header"><h2>服务接入状态</h2><Globe2 size={20} /></div><div className="page-stack" style={{ gap: 12 }}><div className="field-row"><span>站内余额支付</span><span className="tag">可用</span></div><div className="field-row"><span>第三方支付渠道</span><span className="muted small">未接入</span></div><div className="field-row"><span>节点计量与停服</span><Link to="/admin/traffic" className="muted small">查看执行状态</Link></div><div className="field-row"><span>邮件与外部通知</span><span className="muted small">未配置</span></div></div></Card></div></div>;
}

function UserEditor({ row, onClose, onSaved }: { row: User; onClose: () => void; onSaved: () => Promise<void> }) {
  const toast = useToast(); const [name, setName] = useState(row.name); const [status, setStatus] = useState(row.status); const [delta, setDelta] = useState(''); const [confirmed, setConfirmed] = useState(false); const [saving, setSaving] = useState(false);
  const cents = Math.round(Number(delta || 0) * 100);
  return <Modal title="编辑用户" onClose={onClose}><form className="form-grid" onSubmit={async (e) => { e.preventDefault(); if (cents && !confirmed) return toast('请确认余额调整', 'error'); setSaving(true); try { await api(`/admin/users/${row.id}`, { method: 'PATCH', body: JSON.stringify({ name, status, ...(cents ? { balance_delta: cents } : {}) }) }); toast('用户资料已保存'); await onSaved(); onClose(); } catch (err) { toast(normalizedError(err), 'error'); } finally { setSaving(false); } }}><Field label="邮箱" full><input value={row.email} disabled /></Field><Field label="显示名称"><input required maxLength={60} value={name} onChange={(e) => setName(e.target.value)} /></Field><Field label="账户状态"><select value={status} onChange={(e) => setStatus(e.target.value)}><option value="active">正常</option><option value="disabled">停用</option></select></Field><Field label="当前余额"><input value={money(row.balance)} disabled /></Field><Field label="调整余额（元，可负数）"><input inputMode="decimal" type="number" step="0.01" placeholder="0.00" value={delta} onChange={(e) => { setDelta(e.target.value); setConfirmed(false); }} /></Field>{cents !== 0 && <div className="notice full-width"><p>调整后余额：<strong>{money(row.balance + cents)}</strong>。本次调整会记录到余额流水和审计日志。</p><CheckField label="我已核对调整金额与目标账户" value={confirmed} setValue={setConfirmed} /></div>}<Submit saving={saving} onClose={onClose} /></form></Modal>;
}
function UsersPage() {
  const r = useResource<User[]>('/admin/users'); const [search, setSearch] = useState(''); const [editing, setEditing] = useState<User | null>(null);
  const rows = (r.data || []).filter((u) => `${u.name} ${u.email}`.toLowerCase().includes(search.toLowerCase()));
  return <div className="page-stack"><Hero title="用户管理" description="管理账户资料、使用状态和站内余额。"><Refresh reload={r.reload} /></Hero><Card><div className="card-header"><h2>全部用户 <span className="muted small">{rows.length}</span></h2><SearchBox value={search} setValue={setSearch} placeholder="搜索邮箱或名称" /></div><Load {...r}><Table rows={rows} columns={[{ label: '用户', render: (u) => <><strong>{u.name}</strong><div className="muted small">{u.email}</div></> }, { label: '角色', render: (u) => u.role === 'admin' ? '管理员' : '普通用户' }, { label: '账户状态', render: (u) => <Status value={u.status} /> }, { label: '账户余额', render: (u) => money(u.balance) }, { label: '注册时间', render: (u) => date(u.created_at) }, { label: '操作', render: (u) => <button className="button button-ghost" onClick={() => setEditing(u)}><Edit3 size={14} />编辑</button> }]} /></Load></Card>{editing && <UserEditor row={editing} onClose={() => setEditing(null)} onSaved={r.reload} />}</div>;
}

const defaultPlan: Plan = { id: 0, name: '', description: '', traffic_gb: 100, device_limit: 3, speed_mbps: 200, monthly_price: 2000, quarterly_price: 5700, yearly_price: 20000, onetime_price: 0, kind: 'recurring', recommended: false, active: true, sort_order: 0 };
function PlanEditor({ row, onClose, onSaved }: { row: Plan; onClose: () => void; onSaved: () => Promise<void> }) {
  const [form, setForm] = useState<Plan>({ ...row }); const [saving, setSaving] = useState(false); const toast = useToast();
  const set = <K extends keyof Plan>(k: K, value: Plan[K]) => setForm((v) => ({ ...v, [k]: value }));
  return <Modal title={row.id ? '编辑套餐' : '新增套餐'} onClose={onClose} wide><form className="form-grid" onSubmit={async (e) => { e.preventDefault(); setSaving(true); try { await api(row.id ? `/admin/plans/${row.id}` : '/admin/plans', { method: row.id ? 'PATCH' : 'POST', body: JSON.stringify(form) }); toast('套餐已保存'); await onSaved(); onClose(); } catch (err) { toast(normalizedError(err), 'error'); } finally { setSaving(false); } }}><Field label="套餐名称"><input required maxLength={100} value={form.name} onChange={(e) => set('name', e.target.value)} /></Field><Field label="计费类型"><select value={form.kind} onChange={(e) => set('kind', e.target.value as Plan['kind'])}><option value="recurring">周期订阅</option><option value="onetime">一次性流量包</option></select></Field><Field label="套餐流量（GB）"><input type="number" min="0.01" step="0.01" required value={form.traffic_gb} onChange={(e) => set('traffic_gb', Number(e.target.value))} /></Field><Field label="同时使用设备数（0 为不限）"><input type="number" min="0" required value={form.device_limit} onChange={(e) => set('device_limit', Number(e.target.value))} /></Field><Field label="速度上限（Mbps，0 为不限）"><input type="number" min="0" required value={form.speed_mbps} onChange={(e) => set('speed_mbps', Number(e.target.value))} /></Field><Field label="展示排序"><input type="number" value={form.sort_order} onChange={(e) => set('sort_order', Number(e.target.value))} /></Field>{(form.kind === 'onetime' ? [['onetime_price', '一次性价格（元）']] : [['monthly_price', '月付价格（元）'], ['quarterly_price', '季付价格（元）'], ['yearly_price', '年付价格（元）']]).map(([key, label]) => <Field key={key} label={label}><input type="number" min="0" step="0.01" required value={Number(form[key as keyof Plan]) / 100} onChange={(e) => set(key as 'monthly_price', Math.round(Number(e.target.value) * 100))} /></Field>)}<Field label="套餐说明（每行一项）" full><textarea rows={5} value={form.description} onChange={(e) => set('description', e.target.value)} /></Field><CheckField label="上架销售" value={form.active} setValue={(v) => set('active', v)} /><CheckField label="推荐套餐" value={form.recommended} setValue={(v) => set('recommended', v)} /><Submit saving={saving} onClose={onClose} /></form></Modal>;
}
function PlansPage() {
  const r = useResource<Plan[]>('/admin/plans'); const [editing, setEditing] = useState<Plan | null>(null); const toast = useToast(); const [busy, setBusy] = useState<number | null>(null);
  async function toggle(p: Plan) { setBusy(p.id); try { await api(`/admin/plans/${p.id}`, { method: 'PATCH', body: JSON.stringify({ ...p, active: !p.active }) }); await r.reload(); toast(p.active ? '套餐已下架' : '套餐已上架'); } catch (err) { toast(normalizedError(err), 'error'); } finally { setBusy(null); } }
  return <div className="page-stack"><Hero title="套餐与价格" description="维护流量额度、价格和使用权益，前台会同步显示已上架套餐。"><button className="button" onClick={() => setEditing({ ...defaultPlan })}><Plus size={16} />新增套餐</button></Hero><Card><div className="card-header"><h2>套餐列表</h2><Refresh reload={r.reload} /></div><Load {...r}><Table rows={r.data || []} columns={[{ label: '套餐名称', render: (p) => <><strong>{p.name}</strong>{p.recommended && <span className="tag" style={{ marginLeft: 8 }}>推荐</span>}<div className="muted small">{p.kind === 'onetime' ? '一次性流量包' : '周期订阅'}</div></> }, { label: '流量', render: (p) => gb(p.traffic_gb) }, { label: '设备 / 速度', render: (p) => <>{p.device_limit || '不限'} 台 / {p.speed_mbps ? `${p.speed_mbps} Mbps` : '不限速'}</> }, { label: '价格', render: (p) => <>{money(p.kind === 'onetime' ? p.onetime_price : p.monthly_price)}<span className="muted small"> / {p.kind === 'onetime' ? '次' : '月'}</span></> }, { label: '状态', render: (p) => <Status value={p.active ? 'active' : 'disabled'} /> }, { label: '操作', render: (p) => <div className="actions"><button className="button button-ghost" onClick={() => setEditing(p)}>编辑</button><button className="button button-ghost" disabled={busy === p.id} onClick={() => void toggle(p)}>{p.active ? '下架' : '上架'}</button></div> }]} /></Load></Card>{editing && <PlanEditor row={editing} onClose={() => setEditing(null)} onSaved={r.reload} />}</div>;
}

function SubscriptionEditor({ row, onClose, onSaved }: { row: Subscription; onClose: () => void; onSaved: () => Promise<void> }) {
  const [expires, setExpires] = useState(dateInput(row.expires_at)); const [limit, setLimit] = useState(row.traffic_limit); const [used, setUsed] = useState(row.traffic_used); const [status, setStatus] = useState(row.status); const [saving, setSaving] = useState(false); const toast = useToast();
  return <Modal title="调整订阅权益" onClose={onClose}><form className="form-grid" onSubmit={async (e) => { e.preventDefault(); setSaving(true); try { const expires_at = expires ? new Date(`${expires}T23:59:59+08:00`).toISOString() : ''; await api(`/admin/subscriptions/${row.id}`, { method: 'PATCH', body: JSON.stringify({ ...(expires_at ? { expires_at } : {}), traffic_limit: limit, traffic_used: used, status }) }); await onSaved(); toast('订阅权益已更新'); onClose(); } catch (err) { toast(normalizedError(err), 'error'); } finally { setSaving(false); } }}><div className="notice full-width">{row.user_email || `用户 #${row.user_id}`} · {row.plan_name}<p className="small">人工修改将写入操作审计。实际节点的限速与设备限制仍需节点端接入。</p></div><Field label="到期日期（北京时间）"><input type="date" value={expires} onChange={(e) => setExpires(e.target.value)} /></Field><Field label="订阅状态"><select value={status} onChange={(e) => setStatus(e.target.value)}><option value="active">正常</option><option value="suspended">暂停</option><option value="expired">已到期</option></select></Field><Field label="总流量额度（GB）"><input type="number" min="0" step="0.001" required value={limit} onChange={(e) => setLimit(Number(e.target.value))} /></Field><Field label="已用流量（GB）"><input type="number" min="0" step="0.001" required value={used} onChange={(e) => setUsed(Number(e.target.value))} /></Field><Submit saving={saving} onClose={onClose} /></form></Modal>;
}
function TrafficReset({ row, onClose, onSaved }: { row: Subscription; onClose: () => void; onSaved: () => Promise<void> }) {
  const [confirmed, setConfirmed] = useState(false); const [saving, setSaving] = useState(false); const toast = useToast();
  const reset = async () => {
    if (!confirmed || saving) return;
    setSaving(true);
    try {
      await api(`/admin/users/${row.user_id}/traffic/reset`, { method: 'POST' });
      await onSaved(); toast('流量周期已重置，节点将在同步策略后应用'); onClose();
    } catch (err) { toast(normalizedError(err), 'error'); } finally { setSaving(false); }
  };
  return <Modal title="确认重置用户流量" onClose={() => !saving && onClose()}><div className="page-stack"><p>用户：<strong>{row.user_email || `#${row.user_id}`}</strong><br />套餐：{row.plan_name}<br />当前已用：{gb(subscriptionGB(row, 'used'))}</p><div className="notice"><div>重置会清空本周期上传、下载与计费用量，并建立新周期；历史明细保留。账户封禁、人工暂停及到期状态继续生效。操作会写入审计。</div></div><CheckField label="我已核对用户并确认重置当前流量周期" value={confirmed} setValue={setConfirmed} /><div className="actions"><button className="button button-ghost" disabled={saving} onClick={onClose}>取消</button><button className="button button-primary" disabled={!confirmed || saving} onClick={() => void reset()}>{saving ? '正在重置…' : '确认重置流量'}</button></div></div></Modal>;
}
function SubscriptionsPage() {
  const r = useResource<Subscription[]>('/admin/subscriptions'); const [search, setSearch] = useState(''); const [editing, setEditing] = useState<Subscription | null>(null); const [resetting, setResetting] = useState<Subscription | null>(null); const rows = (r.data || []).filter((s) => `${s.user_email} ${s.plan_name}`.toLowerCase().includes(search.toLowerCase()));
  return <div className="page-stack"><Hero title="订阅权益" description="查看套餐生效情况、到期日期与流量额度。"><Refresh reload={r.reload} /></Hero><Card><div className="card-header"><h2>用户订阅</h2><SearchBox value={search} setValue={setSearch} placeholder="搜索用户或套餐" /></div><Load {...r}><Table rows={rows} columns={[{ label: '用户 / 套餐', render: (s) => <><strong>{s.user_email || `#${s.user_id}`}</strong><div className="muted small">{s.plan_name}</div></> }, { label: '已用 / 总流量', render: (s) => <>{gb(subscriptionGB(s, 'used'))} / {gb(subscriptionGB(s, 'limit'))}</> }, { label: '设备 / 速度', render: (s) => <>{s.device_limit || '不限'} 台 / {s.speed_mbps || '不限'} Mbps</> }, { label: '到期时间', render: (s) => s.expires_at ? date(s.expires_at) : '长期有效' }, { label: '服务策略', render: (s) => <span className="tag">{serviceReason(s.service_reason || s.status)}</span> }, { label: '操作', render: (s) => <div className="actions"><button className="button button-ghost" onClick={() => setEditing(s)}>调整权益</button><button className="button button-ghost" onClick={() => setResetting(s)}><RefreshCw size={14} />重置流量</button></div> }]} /></Load></Card><div className="notice">服务策略表示控制面的可用性判定。实际节点执行结果请在 <Link to="/admin/traffic">流量统计</Link> 查看。</div>{editing && <SubscriptionEditor row={editing} onClose={() => setEditing(null)} onSaved={r.reload} />}{resetting && <TrafficReset row={resetting} onClose={() => setResetting(null)} onSaved={r.reload} />}</div>;
}

type AdminNode = Node & {uuid?: string; password?: string; cipher?: string};
const defaultNode: AdminNode = { id: 0, name: '', region: '香港', flag: '🇭🇰', protocol: 'vless', status: 'not_connected', multiplier: 1, tags: '标准线路', host: '', port: 443, tls: true, server_name: '', active: false, sort_order: 0, updated_at: '' };
function NodeEditor({ row, onClose, onSaved }: { row: AdminNode; onClose: () => void; onSaved: () => Promise<void> }) {
  const [form, setForm] = useState<AdminNode>({ ...row }); const [saving, setSaving] = useState(false); const toast = useToast(); const set = <K extends keyof AdminNode>(key: K, value: AdminNode[K]) => setForm((v) => ({ ...v, [key]: value }));
  return <Modal title={row.id ? '编辑节点' : '新增节点'} onClose={onClose} wide><form className="form-grid" onSubmit={async (e) => { e.preventDefault(); setSaving(true); try { await api(row.id ? `/admin/nodes/${row.id}` : '/admin/nodes', { method: row.id ? 'PATCH' : 'POST', body: JSON.stringify(form) }); await onSaved(); toast('节点配置已保存'); onClose(); } catch (err) { toast(normalizedError(err), 'error'); } finally { setSaving(false); } }}><div className="notice full-width">填写公开连接地址与协议参数后，为节点签发 Agent 凭据并部署节点端，才能采集流量与执行停服。设备数及速度限制仍待接入。</div><Field label="节点名称"><input required maxLength={100} value={form.name} onChange={(e) => set('name', e.target.value)} /></Field><Field label="地区"><input required maxLength={40} value={form.region} onChange={(e) => set('region', e.target.value)} /></Field><Field label="地区旗帜（Emoji）"><input maxLength={12} value={form.flag} onChange={(e) => set('flag', e.target.value)} /></Field><Field label="节点协议"><select value={form.protocol.toLowerCase()} onChange={(e) => set('protocol', e.target.value)}><option value="vless">VLESS</option><option value="anytls">ANYTLS</option><option value="shadowsocks">Shadowsocks</option><option value="trojan">Trojan</option><option value="vmess">VMess</option></select></Field><Field label="连接地址"><input value={form.host || ''} placeholder="node.example.com" onChange={(e) => set('host', e.target.value)} /></Field><Field label="端口"><input type="number" min="1" max="65535" value={form.port || 443} onChange={(e) => set('port', Number(e.target.value))} /></Field><Field label="TLS 服务器名称（SNI）"><input value={form.server_name || ''} onChange={(e) => set('server_name', e.target.value)} /></Field><Field label="流量倍率"><input type="number" min="0.01" max="100" step="0.01" required value={form.multiplier} onChange={(e) => set('multiplier', Number(e.target.value))} /></Field><Field label="节点标签"><input value={form.tags} onChange={(e) => set('tags', e.target.value)} /></Field><Field label="展示排序"><input type="number" value={form.sort_order} onChange={(e) => set('sort_order', Number(e.target.value))} /></Field>{!form.managed && ['vless', 'vmess'].includes(form.protocol.toLowerCase()) && <Field label="UUID"><input autoComplete="off" value={form.uuid || ''} onChange={(e) => set('uuid', e.target.value)} placeholder="节点服务端已配置的 UUID" /></Field>}{!form.managed && ['anytls', 'shadowsocks', 'ss', 'trojan'].includes(form.protocol.toLowerCase()) && <Field label="节点连接密码"><input type="password" autoComplete="new-password" value={form.password || ''} onChange={(e) => set('password', e.target.value)} placeholder="填写节点端对应的连接密码" /></Field>}{['shadowsocks', 'ss'].includes(form.protocol.toLowerCase()) && <Field label="加密方法"><select value={form.cipher || 'aes-128-gcm'} onChange={(e) => set('cipher', e.target.value)}><option value="aes-128-gcm">aes-128-gcm</option><option value="aes-256-gcm">aes-256-gcm</option><option value="chacha20-ietf-poly1305">chacha20-ietf-poly1305</option></select></Field>}<CheckField label="启用节点" value={form.active} setValue={(v) => set('active', v)} /><CheckField label="启用 TLS" value={Boolean(form.tls)} setValue={(v) => set('tls', v)} /><Submit saving={saving} onClose={onClose} /></form></Modal>;
}
function AgentToken({ row, onClose, onSaved }: { row: AdminNode; onClose: () => void; onSaved: () => Promise<void> }) {
  const [engine, setEngine] = useState<'xray'|'sing-box'>(row.agent_engine || 'xray'); const [portStart, setPortStart] = useState(row.port_start || 20000); const [portEnd, setPortEnd] = useState(row.port_end || 20999); const [confirmed, setConfirmed] = useState(!row.managed); const [saving, setSaving] = useState(false); const [token, setToken] = useState(''); const toast = useToast();
  const copy = async () => { try { await navigator.clipboard.writeText(token); toast('节点凭据已复制，请保存在节点端'); } catch { toast('请选中凭据手动复制', 'error'); } };
  return <Modal title={token ? '保存节点 Agent 凭据' : row.managed ? '重新签发 Agent 凭据' : '接入节点 Agent'} onClose={() => !saving && onClose()}><div className="page-stack"><p><strong>{row.name}</strong> · {row.protocol.toUpperCase()}</p>{token ? <><div className="notice">此凭据只在本次窗口显示。关闭前请保存，勿分享给其他人。旧凭据已失效。</div><Field label="节点凭据（可选中复制）" full><textarea readOnly autoComplete="off" rows={3} value={token} onFocus={(e) => e.currentTarget.select()} style={{ overflowWrap: 'anywhere' }} /></Field><button className="button button-primary" onClick={() => void copy()}><Copy size={16} />复制节点凭据</button><p className="muted small">在节点设置 NICECLOUD_NODE_TOKEN 环境变量，按项目内 node-agent/README.md 构建并运行对应内核的 Agent。使用 TLS 时配置证书与私钥，开放所选用户端口范围。Agent 启动、流量上报与停服结果可在流量统计页检查。</p><Link className="button button-ghost" to="/admin/traffic" onClick={onClose}>查看执行状态</Link></> : <form className="form-grid" onSubmit={async (e) => { e.preventDefault(); if (!confirmed) return; setSaving(true); try { const result = await api<{token:string;node_id:number}>(`/admin/nodes/${row.id}/agent-token`, { method: 'POST', body: JSON.stringify({engine,port_start:portStart,port_end:portEnd}) }); setToken(result.token); await onSaved(); } catch (err) { toast(normalizedError(err), 'error'); } finally { setSaving(false); } }}><Field label="代理内核" full><select value={engine} onChange={(e) => setEngine(e.target.value as 'xray'|'sing-box')}><option value="xray">Xray</option><option value="sing-box">sing-box（需 with_v2ray_api）</option></select></Field><Field label="用户端口起始"><input type="number" required min="1024" max="65535" value={portStart} onChange={(e) => setPortStart(Number(e.target.value))} /></Field><Field label="用户端口结束"><input type="number" required min={portStart} max="65535" value={portEnd} onChange={(e) => setPortEnd(Number(e.target.value))} /></Field><div className="notice full-width">每位用户分配独立端口与进程。签发凭据不会自动部署节点，请参照项目内 node-agent/README.md 完成安装。已有共享进程节点需要迁移到托管方式。</div>{row.managed && <div className="full-width"><CheckField label="重新签发会立即撤销旧凭据，我已安排更新该节点 Agent" value={confirmed} setValue={setConfirmed} /></div>}<div className="actions full-width"><button type="button" className="button button-ghost" disabled={saving} onClick={onClose}>取消</button><button className="button button-primary" disabled={saving || !confirmed}>{saving ? '正在签发…' : '签发节点凭据'}</button></div></form>}</div></Modal>;
}
function NodesPage() {
  const r = useResource<AdminNode[]>('/admin/nodes'); const [editing, setEditing] = useState<AdminNode | null>(null); const [agent, setAgent] = useState<AdminNode | null>(null); const [search, setSearch] = useState(''); const rows = (r.data || []).filter((n) => `${n.name} ${n.region} ${n.protocol}`.toLowerCase().includes(search.toLowerCase()));
  return <div className="page-stack"><Hero title="节点与线路" description="维护连接参数、流量倍率与托管 Agent 凭据。"><button className="button" onClick={() => setEditing({ ...defaultNode })}><Plus size={16} />新增节点</button></Hero><Card><div className="card-header"><h2>节点配置</h2><SearchBox value={search} setValue={setSearch} placeholder="搜索节点或地区" /></div><Load {...r}><Table rows={rows} columns={[{ label: '节点', render: (n) => <><strong>{n.flag} {n.name}</strong><div className="muted small">{n.region} · {n.tags}</div></> }, { label: '协议 / 地址', render: (n) => <><span className="tag">{n.protocol.toUpperCase()}</span><div className="muted small">{n.host || '未配置'}{n.managed ? `:${n.port_start}–${n.port_end}` : n.port ? `:${n.port}` : ''}</div></> }, { label: '流量倍率', render: (n) => `${n.multiplier}×` }, { label: '启用', render: (n) => <Status value={n.active ? 'active' : 'disabled'} /> }, { label: '接入状态', render: (n) => n.managed ? <><span className="tag">{n.agent_engine} 托管</span><div className="muted small">{n.agent_last_seen ? `最近联络 ${date(n.agent_last_seen, true)}` : '尚未收到 Agent 联络'}</div></> : <Status value={n.status} /> }, { label: '操作', render: (n) => <div className="actions"><button className="button button-ghost" onClick={() => setEditing(n)}>编辑节点</button><button className="button button-ghost" onClick={() => setAgent(n)}><KeyRound size={14} />{n.managed ? '重签凭据' : '接入 Agent'}</button></div> }]} /></Load></Card>{editing && <NodeEditor row={editing} onClose={() => setEditing(null)} onSaved={r.reload} />}{agent && <AgentToken row={agent} onClose={() => setAgent(null)} onSaved={r.reload} />}</div>;
}

function OrdersPage() {
  const r = useResource<Order[]>('/admin/orders'); const [search, setSearch] = useState(''); const [status, setStatus] = useState('all'); const [selected, setSelected] = useState<Order | null>(null); const rows = (r.data || []).filter((o) => `${o.order_no} ${o.user_email} ${o.plan_name}`.toLowerCase().includes(search.toLowerCase()) && (status === 'all' || o.status === status));
  return <div className="page-stack"><Hero title="订单管理" description="查看订单记录、支付金额和服务变更状态。"><Refresh reload={r.reload} /></Hero><Card><div className="card-header"><h2>全部订单</h2><div className="actions"><select aria-label="订单状态筛选" value={status} onChange={(e) => setStatus(e.target.value)}><option value="all">全部状态</option><option value="pending">待支付</option><option value="paid">已支付</option><option value="cancelled">已取消</option></select><SearchBox value={search} setValue={setSearch} placeholder="搜索订单、邮箱或套餐" /></div></div><Load {...r}><Table rows={rows} columns={[{ label: '订单', render: (o) => <><strong>{o.plan_name}</strong><div className="muted small">{o.order_no}</div></> }, { label: '用户', render: (o) => o.user_email || `#${o.user_id}` }, { label: '周期', render: (o) => periodNames[o.period] || o.period }, { label: '金额', render: (o) => money(o.amount) }, { label: '状态', render: (o) => <Status value={o.status} /> }, { label: '创建时间', render: (o) => date(o.created_at) }, { label: '操作', render: (o) => <button className="button button-ghost" onClick={() => setSelected(o)}>详情</button> }]} /></Load></Card>{selected && <Modal title="订单详情" onClose={() => setSelected(null)}><dl className="detail-grid">{[['订单编号', selected.order_no], ['用户', selected.user_email || `#${selected.user_id}`], ['套餐', selected.plan_name], ['计费周期', periodNames[selected.period] || selected.period], ['订单金额', money(selected.amount)], ['创建时间', date(selected.created_at)], ['支付时间', selected.paid_at ? date(selected.paid_at) : '尚未支付']].map(([label, val]) => <div key={label}><dt className="muted small">{label}</dt><dd style={{ margin: '7px 0 16px', overflowWrap: 'anywhere' }}>{val}</dd></div>)}</dl><Status value={selected.status} /></Modal>}</div>;
}

function FinancePage() {
  const r = useResource<Ledger[]>('/admin/ledger'); const [search, setSearch] = useState(''); const rows = (r.data || []).filter((l) => `${l.user_email} ${l.description} ${l.kind}`.toLowerCase().includes(search.toLowerCase()));
  const credits = (r.data || []).filter((l) => l.amount > 0).reduce((s, l) => s + l.amount, 0); const debits = (r.data || []).filter((l) => l.amount < 0).reduce((s, l) => s - l.amount, 0);
  return <div className="page-stack"><Hero title="支付与账务" description="每一笔余额变动都有记录，金额以服务端账务为准。"><Refresh reload={r.reload} /></Hero><div className="grid-2"><Stat label="记录入账金额" value={money(credits)} icon={<ArrowDownLeft size={24} />} tone="green" /><Stat label="记录出账金额" value={money(debits)} icon={<ArrowUpRight size={24} />} tone="orange" /></div><div className="notice"><strong>第三方支付渠道尚未接入。</strong> 当前支持站内余额支付及管理员余额调整。支付商户、回调验签、退款与对账需要独立联调。</div><Card><div className="card-header"><h2>余额流水</h2><SearchBox value={search} setValue={setSearch} placeholder="搜索用户或流水说明" /></div><Load {...r}><Table rows={rows} columns={[{ label: '用户', render: (l) => l.user_email || `#${l.user_id}` }, { label: '变动金额', render: (l) => <strong style={{ color: l.amount >= 0 ? 'var(--success, #319b78)' : 'var(--danger, #db6964)' }}>{l.amount > 0 ? '+' : ''}{money(l.amount)}</strong> }, { label: '变动后余额', render: (l) => money(l.balance_after) }, { label: '类型', render: (l) => l.kind }, { label: '说明', render: (l) => l.description }, { label: '时间', render: (l) => date(l.created_at) }]} /></Load></Card></div>;
}
function EnforcementStatus({ row, at }: { row: TrafficEnforcement; at: number }) {
  const lastSeen = row.last_seen ? new Date(row.last_seen).getTime() : 0;
  if (!lastSeen || at - lastSeen > (row.lease_seconds || 15) * 1000) return <><span className="status status-red"><i />{lastSeen ? '节点失联 · 未确认' : 'Agent 未接入'}</span><p className="muted small">节点租约到期后应自动停止，等待重新联络核实。</p></>;
  if (row.error) return <><span className="status status-red"><i />执行失败</span><p className="muted small">{row.error}</p></>;
  if (row.applied_enabled === null) return <span className="status status-orange"><i />{row.desired_enabled ? '待启用确认' : '待停服确认'}</span>;
  if (row.applied_enabled !== row.desired_enabled) return <span className="status status-red"><i />状态不符 · 待同步</span>;
  return <span className={`status status-${row.applied_enabled ? 'green' : 'gray'}`}><i />{row.applied_enabled ? '启用已确认' : '停服已确认'}</span>;
}
function TrafficPage() {
  const r = useResource<TrafficRecord[]>('/admin/traffic'); const enforcement = useResource<TrafficEnforcement[]>('/admin/traffic/enforcement'); const [search, setSearch] = useState(''); const [source, setSource] = useState('all'); const [at, setAt] = useState(Date.now());
  useEffect(() => { const timer = setInterval(() => { setAt(Date.now()); }, 1000); const poll = setInterval(() => { void enforcement.reload(); }, 5000); return () => { clearInterval(timer); clearInterval(poll); }; }, [enforcement.reload]);
  const rows = (r.data || []).filter((t) => `${t.user_email} ${t.date} ${t.node_name}`.toLowerCase().includes(search.toLowerCase()) && (source === 'all' || t.source === source)); const totals = rows.reduce((s, row) => ({ upload: s.upload + trafficGB(row, 'upload'), download: s.download + trafficGB(row, 'download'), total: s.total + trafficGB(row, 'total') }), { upload: 0, download: 0, total: 0 });
  const policies = (enforcement.data || []).filter((row) => `${row.user_email} ${row.node_name}`.toLowerCase().includes(search.toLowerCase())).map((row) => ({ ...row, id: `${row.node_id}:${row.user_id}` }));
  return <div className="page-stack"><Hero title="流量与停服执行" description="查看节点计量、服务策略及实际执行确认。"><Refresh reload={async () => { await Promise.all([r.reload(), enforcement.reload()]); }} /></Hero><div className="grid-3"><Stat label="上传流量" value={gb(totals.upload)} icon={<ArrowUpRight size={22} />} tone="purple" /><Stat label="下载流量" value={gb(totals.download)} icon={<ArrowDownLeft size={22} />} tone="blue" /><Stat label="计费总流量" value={gb(totals.total)} icon={<Activity size={22} />} tone="green" /></div><div className="notice">达到流量额度即下发停服策略；只有节点成功执行并确认当前策略，才显示“停服已确认”。节点失联或尚未确认时，实际状态待核实。设备数量与速度限制另需接入。</div><Card><div className="card-header"><h2>节点执行状态</h2><SearchBox value={search} setValue={setSearch} placeholder="搜索用户、节点或日期" /></div><p className="muted small">每 5 秒同步执行状态；超过策略租约未联络会标记失联。</p><Load {...enforcement} loading={enforcement.loading && !enforcement.data}><Table rows={policies} empty="暂无托管用户策略" columns={[{label:'用户 / 节点',render:(row) => <><strong>{row.user_email || `#${row.user_id}`}</strong><div className="muted small">{row.node_name}</div></>},{label:'期望服务',render:(row) => <><span className="tag">{row.desired_enabled ? '允许使用' : '停止服务'}</span><div className="muted small">{serviceReason(row.reason)}</div></>},{label:'节点执行',render:(row) => <EnforcementStatus row={row} at={at} />},{label:'最近确认',render:(row) => row.ack_at ? date(row.ack_at,true) : '尚未确认'},{label:'最近联络',render:(row) => row.last_seen ? date(row.last_seen,true) : '尚未联络'}]} /></Load></Card><Card><div className="card-header"><div><h2>流量明细</h2><p className="muted small">整数 bytes 计量；计费用量 =（上传 + 下载）× 倍率，1 GB = 1024³ bytes。</p></div><select aria-label="筛选流量来源" value={source} onChange={(e) => setSource(e.target.value)}><option value="all">全部来源</option><option value="metered">节点计量</option><option value="demo">演示数据</option></select></div><Load {...r}><Table rows={rows} columns={[{ label: '用户', render: (t) => t.user_email || `#${t.user_id}` }, { label: '时间', render: (t) => date(t.date,true) }, { label: '节点', render: (t) => t.node_name || '—' }, { label: '上传', render: (t) => gb(trafficGB(t, 'upload')) }, { label: '下载', render: (t) => gb(trafficGB(t, 'download')) }, { label: '倍率', render: (t) => `${t.multiplier}×` }, { label: '计费用量', render: (t) => <strong>{gb(trafficGB(t, 'total'))}</strong> }, { label: '来源', render: (t) => <span className="tag">{t.source === 'metered' ? '节点计量' : t.source === 'demo' ? '演示数据' : '历史记录'}</span> }]} /></Load></Card></div>;
}

function InvitesPage() {
  const c = useResource<Commission[]>('/admin/commissions'); const w = useResource<Withdrawal[]>('/admin/withdrawals'); const [tab, setTab] = useState('withdrawals'); const [review, setReview] = useState<{ row: Withdrawal; status: 'approved' | 'rejected' } | null>(null); const [saving, setSaving] = useState(false); const toast = useToast();
  return <div className="page-stack"><Hero title="邀请与佣金" description="查看返佣记录，审核用户提交的提现申请。" /><div className="tabs"><button className={`tab ${tab === 'withdrawals' ? 'active' : ''}`} onClick={() => setTab('withdrawals')}>提现申请</button><button className={`tab ${tab === 'commissions' ? 'active' : ''}`} onClick={() => setTab('commissions')}>佣金明细</button></div>{tab === 'withdrawals' ? <Card><div className="card-header"><h2>提现申请</h2><Refresh reload={w.reload} /></div><Load {...w}><Table rows={w.data || []} columns={[{ label: '用户', render: (r) => r.user_email || `#${r.user_id}` }, { label: '申请金额', render: (r) => money(r.amount) }, { label: '收款信息', render: (r) => <span style={{ overflowWrap: 'anywhere', maxWidth: 220, display: 'block' }}>{r.account}</span> }, { label: '申请时间', render: (r) => date(r.created_at) }, { label: '状态', render: (r) => <Status value={r.status} /> }, { label: '操作', render: (r) => r.status === 'pending' ? <div className="actions"><button className="button button-ghost" onClick={() => setReview({ row: r, status: 'approved' })}><Check size={14} />批准</button><button className="button button-ghost" onClick={() => setReview({ row: r, status: 'rejected' })}><X size={14} />拒绝</button></div> : '已处理' }]} /></Load></Card> : <Card><div className="card-header"><h2>佣金明细</h2><Refresh reload={c.reload} /></div><Load {...c}><Table rows={c.data || []} columns={[{ label: '受益用户', render: (r) => r.user_email || `#${r.user_id}` }, { label: '订单编号', render: (r) => r.order_no }, { label: '佣金金额', render: (r) => money(r.amount) }, { label: '状态', render: (r) => <Status value={r.status} /> }, { label: '时间', render: (r) => date(r.created_at) }]} /></Load></Card>}{review && <Modal title={review.status === 'approved' ? '批准提现申请' : '拒绝提现申请'} onClose={() => setReview(null)}><div className="page-stack"><p>用户：{review.row.user_email || `#${review.row.user_id}`}<br />申请金额：<strong>{money(review.row.amount)}</strong></p><div className="notice">{review.status === 'approved' ? '批准会更新申请处理状态，不会自动向外部收款账户转账。请先完成线下打款并核对收款信息。' : '拒绝后按照服务端规则恢复可提现佣金，处理结果将记录到审计日志。'}</div><div className="actions" style={{ justifyContent: 'flex-end' }}><button className="button button-ghost" onClick={() => setReview(null)}>取消</button><button className="button button-primary" disabled={saving} onClick={async () => { setSaving(true); try { await api(`/admin/withdrawals/${review.row.id}`, { method: 'PATCH', body: JSON.stringify({ status: review.status }) }); toast('申请已处理'); await w.reload(); setReview(null); } catch (err) { toast(normalizedError(err), 'error'); } finally { setSaving(false); } }}>{saving ? '处理中…' : '确认处理'}</button></div></div></Modal>}</div>;
}

function TicketConversation({ id, onClose, onSaved }: { id: number; onClose: () => void; onSaved: () => Promise<void> }) {
  const r = useResource<Ticket>(`/tickets/${id}`); const [message, setMessage] = useState(''); const [saving, setSaving] = useState(false); const toast = useToast();
  async function reply() { if (!message.trim()) return; setSaving(true); try { await api(`/tickets/${id}/messages`, { method: 'POST', body: JSON.stringify({ message }) }); setMessage(''); await r.reload(); await onSaved(); toast('回复已发送'); } catch (err) { toast(normalizedError(err), 'error'); } finally { setSaving(false); } }
  return <Modal title={r.data?.subject || '工单详情'} onClose={onClose} wide><Load {...r}>{r.data && <div className="page-stack"><div className="field-row"><span className="muted small">{r.data.user_email || `用户 #${r.data.user_id}`} · {date(r.data.created_at)}</span><Status value={r.data.status} /></div><div className="message-thread">{(r.data.messages || []).map((m) => <div key={m.id} className={`message-bubble ${m.role === 'admin' ? 'admin' : ''}`}><div className="muted small">{m.role === 'admin' ? '客服团队' : '用户'} · {date(m.created_at)}</div><p style={{ whiteSpace: 'pre-wrap', overflowWrap: 'anywhere' }}>{m.message}</p></div>)}</div>{r.data.status !== 'closed' && <form className="page-stack" style={{ gap: 12 }} onSubmit={(e) => { e.preventDefault(); void reply(); }}><label className="form-field"><span>回复用户</span><textarea required maxLength={10000} rows={4} value={message} onChange={(e) => setMessage(e.target.value)} placeholder="输入处理建议或需要补充的信息…" /></label><div className="actions" style={{ justifyContent: 'flex-end' }}><button type="button" disabled={saving} className="button button-ghost" onClick={async () => { setSaving(true); try { await api(`/tickets/${id}/close`, { method: 'POST' }); await r.reload(); await onSaved(); toast('工单已关闭'); } catch (err) { toast(normalizedError(err), 'error'); } finally { setSaving(false); } }}>关闭工单</button><button className="button button-primary" disabled={saving || !message.trim()}>{saving ? '处理中…' : '发送回复'}</button></div></form>}</div>}</Load></Modal>;
}
function TicketsPage() {
  const r = useResource<Ticket[]>('/admin/tickets'); const [status, setStatus] = useState('all'); const [selected, setSelected] = useState<number | null>(null); const [search, setSearch] = useState(''); const rows = (r.data || []).filter((t) => (status === 'all' || (status === 'open' ? t.status !== 'closed' : t.status === 'closed')) && `${t.subject} ${t.user_email}`.toLowerCase().includes(search.toLowerCase()));
  return <div className="page-stack"><Hero title="工单处理" description="集中查看用户问题，跟进回复和处理进度。"><Refresh reload={r.reload} /></Hero><Card><div className="card-header"><h2>客户工单</h2><div className="actions"><select aria-label="工单状态筛选" value={status} onChange={(e) => setStatus(e.target.value)}><option value="all">全部状态</option><option value="open">处理中</option><option value="closed">已关闭</option></select><SearchBox value={search} setValue={setSearch} placeholder="搜索主题或用户" /></div></div><Load {...r}><Table rows={rows} columns={[{ label: '主题', render: (t) => <><strong>{t.subject}</strong><div className="muted small">#{t.id}</div></> }, { label: '用户', render: (t) => t.user_email || `#${t.user_id}` }, { label: '优先级', render: (t) => ({ low: '低', normal: '普通', high: '高' })[t.priority] || t.priority }, { label: '状态', render: (t) => <Status value={t.status} /> }, { label: '更新时间', render: (t) => date(t.updated_at) }, { label: '操作', render: (t) => <button className="button button-ghost" onClick={() => setSelected(t.id)}>查看与回复</button> }]} /></Load></Card>{selected !== null && <TicketConversation id={selected} onClose={() => setSelected(null)} onSaved={r.reload} />}</div>;
}

const articleKinds = { doc: '使用文档', announcement: '公告', notice: '站内通知' };
const defaultArticle: Article = { id: 0, title: '', category: '使用指南', kind: 'doc', body: '', published: false, updated_at: '' };
function ArticleEditor({ row, onClose, onSaved }: { row: Article; onClose: () => void; onSaved: () => Promise<void> }) {
  const [form, setForm] = useState<Article>({ ...row }); const [saving, setSaving] = useState(false); const toast = useToast();
  return <Modal title={row.id ? '编辑内容' : '新增内容'} onClose={onClose} wide><form className="form-grid" onSubmit={async (e) => { e.preventDefault(); setSaving(true); try { await api(row.id ? `/admin/articles/${row.id}` : '/admin/articles', { method: row.id ? 'PATCH' : 'POST', body: JSON.stringify(form) }); await onSaved(); toast('内容已保存'); onClose(); } catch (err) { toast(normalizedError(err), 'error'); } finally { setSaving(false); } }}><Field label="标题" full><input required maxLength={200} value={form.title} onChange={(e) => setForm((v) => ({ ...v, title: e.target.value }))} /></Field><Field label="内容类型"><select value={form.kind} onChange={(e) => setForm((v) => ({ ...v, kind: e.target.value as Article['kind'] }))}>{Object.entries(articleKinds).map(([kind, label]) => <option key={kind} value={kind}>{label}</option>)}</select></Field><Field label="内容分类"><input required maxLength={60} value={form.category} onChange={(e) => setForm((v) => ({ ...v, category: e.target.value }))} /></Field><Field label="正文（纯文本）" full><textarea required maxLength={100000} rows={13} value={form.body} onChange={(e) => setForm((v) => ({ ...v, body: e.target.value }))} placeholder="填写教程、公告或通知正文。段落和换行会保留。" /></Field><CheckField label="发布，允许用户查看" value={form.published} setValue={(published) => setForm((v) => ({ ...v, published }))} /><Submit saving={saving} onClose={onClose} /></form></Modal>;
}
function ContentPage() {
  const r = useResource<Article[]>('/admin/articles'); const [kind, setKind] = useState('all'); const [editing, setEditing] = useState<Article | null>(null); const [search, setSearch] = useState(''); const rows = (r.data || []).filter((a) => (kind === 'all' || a.kind === kind) && `${a.title} ${a.category}`.toLowerCase().includes(search.toLowerCase()));
  return <div className="page-stack"><Hero title="公告与文档" description="维护使用指南、服务公告和站内通知。"><button className="button" onClick={() => setEditing({ ...defaultArticle })}><Plus size={16} />新增内容</button></Hero><Card><div className="card-header"><h2>内容管理</h2><div className="actions"><select aria-label="内容类型筛选" value={kind} onChange={(e) => setKind(e.target.value)}><option value="all">全部类型</option>{Object.entries(articleKinds).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select><SearchBox value={search} setValue={setSearch} placeholder="搜索标题或分类" /></div></div><Load {...r}><Table rows={rows} columns={[{ label: '标题', render: (a) => <div className="actions"><FileText size={16} /><strong>{a.title}</strong></div> }, { label: '类型', render: (a) => articleKinds[a.kind] }, { label: '分类', render: (a) => a.category }, { label: '发布状态', render: (a) => <span className="tag">{a.published ? '已发布' : '草稿 / 隐藏'}</span> }, { label: '更新时间', render: (a) => date(a.updated_at) }, { label: '操作', render: (a) => <button className="button button-ghost" onClick={() => setEditing(a)}>编辑</button> }]} /></Load></Card>{editing && <ArticleEditor row={editing} onClose={() => setEditing(null)} onSaved={r.reload} />}</div>;
}

function SettingsEditor({ initial, reload }: { initial: Record<string, string>; reload: () => Promise<void> }) {
  const [form, setForm] = useState({ ...initial }); const [saving, setSaving] = useState(false); const toast = useToast();
  const fields = [{ key: 'site_name', label: '站点名称', type: 'text' }, { key: 'site_description', label: '站点描述', type: 'text' }, { key: 'contact_email', label: '联系邮箱', type: 'email' }];
  return <form className="form-grid" onSubmit={async (e) => { e.preventDefault(); setSaving(true); try { await api('/admin/settings', { method: 'PATCH', body: JSON.stringify(Object.fromEntries(Object.entries(form).filter(([key]) => ['site_name', 'site_description', 'contact_email', 'registration_enabled', 'invite_rate'].includes(key)))) }); await reload(); toast('站点设置已保存，刷新页面可查看品牌更新'); } catch (err) { toast(normalizedError(err), 'error'); } finally { setSaving(false); } }}>{fields.map((f) => <Field key={f.key} label={f.label} full><input type={f.type} required={f.key === 'site_name'} maxLength={f.key === 'site_description' ? 500 : 200} value={form[f.key] || ''} onChange={(e) => setForm((v) => ({ ...v, [f.key]: e.target.value }))} /></Field>)}{Object.hasOwn(initial, 'registration_enabled') && <Field label="开放注册"><select value={form.registration_enabled} onChange={(e) => setForm((v) => ({ ...v, registration_enabled: e.target.value }))}><option value="true">开放</option><option value="false">关闭</option></select></Field>}{Object.hasOwn(initial, 'invite_rate') && <Field label="佣金比例（0–1）"><input type="number" min="0" max="1" step="0.01" value={form.invite_rate} onChange={(e) => setForm((v) => ({ ...v, invite_rate: e.target.value }))} /></Field>}<div className="actions full-width" style={{ justifyContent: 'flex-end' }}><button disabled={saving} className="button button-primary">{saving ? '正在保存…' : '保存站点设置'}</button></div></form>;
}
function SettingsPage() {
  const r = useResource<Record<string, string>>('/admin/settings');
  return <div className="page-stack"><Hero title="站点设置" description="配置服务中心的公开品牌信息与基础运营选项。" /><div className="grid-2"><Card><div className="card-header"><h2>基础信息</h2><Globe2 size={20} /></div><Load {...r}>{r.data && <SettingsEditor key={JSON.stringify(r.data)} initial={r.data} reload={r.reload} />}</Load></Card><Card><div className="card-header"><h2>待接入配置</h2><ShieldCheck size={20} /></div><div className="page-stack"><div><strong>第三方支付</strong><p className="muted small">需要支付商户、回调地址和验签配置。</p></div><div><strong>真实节点服务</strong><p className="muted small">节点计量与超额停服使用托管 Agent，需按 node-agent/README.md 部署内核与证书；设备数及限速尚待接入。</p></div><div><strong>邮件通知</strong><p className="muted small">需要 SMTP 或通知服务。找回密码与到期提醒尚不能外发。</p></div><div><strong>语言与客户端兼容</strong><p className="muted small">完整多语言、客户端格式兼容矩阵尚待补齐与实际导入验证。</p></div></div></Card></div></div>;
}

function AuditPage() {
  const r = useResource<Audit[]>('/admin/audit'); const [search, setSearch] = useState(''); const rows = useMemo(() => (r.data || []).filter((a) => `${a.actor} ${a.action} ${a.target}`.toLowerCase().includes(search.toLowerCase())), [r.data, search]);
  return <div className="page-stack"><Hero title="日志与任务" description="追踪重要管理操作，查看变更来源和目标。"><Refresh reload={r.reload} /></Hero><div className="notice"><strong>任务监控面板尚未接入。</strong> 此页展示已持久化的操作审计；外部通知结果及重试队列监控仍待开发。节点策略执行情况可在流量统计页查看。</div><Card><div className="card-header"><h2>操作审计</h2><SearchBox value={search} setValue={setSearch} placeholder="搜索操作人、动作或对象" /></div><Load {...r}><Table rows={rows} columns={[{ label: '操作人', render: (a) => a.actor }, { label: '动作', render: (a) => <span className="tag">{a.action}</span> }, { label: '目标 / 详情', render: (a) => <span style={{ maxWidth: 420, whiteSpace: 'pre-wrap', overflowWrap: 'anywhere', display: 'block' }}>{a.target}</span> }, { label: '操作时间', render: (a) => date(a.created_at) }]} /></Load></Card></div>;
}

export function AdminPages({ page }: { page: string }) {
  switch (page) {
    case 'overview': return <Overview />;
    case 'users': return <UsersPage />;
    case 'plans': return <PlansPage />;
    case 'subscriptions': return <SubscriptionsPage />;
    case 'nodes': return <NodesPage />;
    case 'orders': return <OrdersPage />;
    case 'finance': return <FinancePage />;
    case 'traffic': return <TrafficPage />;
    case 'invites': return <InvitesPage />;
    case 'tickets': return <TicketsPage />;
    case 'content': return <ContentPage />;
    case 'settings': return <SettingsPage />;
    case 'audit': return <AuditPage />;
    default: return <Card><Empty title="管理页面不存在" description="请通过侧边导航选择功能。" action={<Link className="button button-primary" to="/admin/overview">返回运营概览</Link>} /></Card>;
  }
}
